1	type Customer = { yearsWithMHPCO: number };
2	type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
3	type Step = { op: "quote"; items: Item[] };
4	type Scenario = { customer: Customer; steps: Step[] };
5	
6	type QuoteResult = { premium: number };
7	type ScenarioResult = { results: QuoteResult[] };
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_PCT = 0.10;
11	const CURSE_PCT = 0.50;
12	const FLOAT_TOLERANCE = 1e-9;
13	const BLOCK_SIZE = 3;
14	const BLOCK_PREMIUM = 60;
15	
16	const BASE_PREMIUM: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	};
24	
25	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
26	
27	const isComponentType = (type: string): boolean => COMPONENT_TYPES.has(type);
28	
29	const roundUp = (n: number): number => Math.ceil(n - FLOAT_TOLERANCE);
30	
31	const countByType = (items: Item[]): Map<string, number> => {
32	  const counts = new Map<string, number>();
33	  for (const item of items) {
34	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
35	  }
36	  return counts;
37	};
38	
39	const groupBasePremium = (type: string, count: number): number =>
40	  isComponentType(type) && count === BLOCK_SIZE
41	    ? BLOCK_PREMIUM
42	    : count * BASE_PREMIUM[type];
43	
44	const sumBasePremiums = (items: Item[]): number => {
45	  let total = 0;
46	  for (const [type, count] of countByType(items)) {
47	    total += groupBasePremium(type, count);
48	  }
49	  return total;
50	};
51	
52	const itemSurcharges = (items: Item[]): number => {
53	  let total = 0;
54	  for (const item of items) {
55	    if (item.cursed) total += BASE_PREMIUM[item.type] * CURSE_PCT;
56	  }
57	  return total;
58	};
59	
60	const computeQuotePremium = (items: Item[]): number => {
61	  const policyBase = sumBasePremiums(items);
62	  const surcharges = itemSurcharges(items);
63	  const firstIns = policyBase * FIRST_INSURANCE_PCT;
64	  return roundUp(policyBase + surcharges + firstIns + PROCESSING_FEE);
65	};
66	
67	export const runScenario = (scenario: Scenario): ScenarioResult => ({
68	  results: scenario.steps.map((step) => ({ premium: computeQuotePremium(step.items) })),
69	});
70

